import os
keyfile = os.environ.get('GALAXY_API_KEY_FILE','')
with open(keyfile) as f:
    api_key = f.read().strip()

from bioblend.galaxy import GalaxyInstance
gi = GalaxyInstance(url='https://usegalaxy.org', key=api_key)
hist_id = 'bbd44e69cb8906b5bee2208467d81018'

# Dataset IDs for full tables
datasets = {
    'Cele': 'f9cad7b01a472135a3752a88a883b996',
    'Ggal': 'f9cad7b01a4721350cfe34c3d4ba1879',
    'Ncra': 'f9cad7b01a472135ca7f302f956bbc3a',
    'Scer': 'f9cad7b01a4721351845418f23a6fac0',
}

all_orthologs = {}
for name, ds_id in datasets.items():
    content = gi.datasets.download_dataset(ds_id)
    content = content.decode() if isinstance(content, bytes) else content

    # Parse: extract Busco IDs with Status="Complete" (single-copy)
    complete_single = set()
    all_statuses = {}
    for line in content.split('\n'):
        if line.startswith('#') or not line.strip():
            continue
        parts = line.split('\t')
        if len(parts) >= 2:
            busco_id = parts[0]
            status = parts[1]
            if busco_id not in all_statuses or status == 'Complete':
                all_statuses[busco_id] = status

    # "Complete" in BUSCO table = single-copy complete
    # "Duplicated" = multi-copy complete
    complete_single = {bid for bid, status in all_statuses.items() if status == 'Complete'}
    duplicated = {bid for bid, status in all_statuses.items() if status == 'Duplicated'}
    fragmented = {bid for bid, status in all_statuses.items() if status == 'Fragmented'}
    missing = {bid for bid, status in all_statuses.items() if status == 'Missing'}

    all_orthologs[name] = complete_single
    print(f"{name}: Complete single-copy = {len(complete_single)}, Duplicated = {len(duplicated)}, Fragmented = {len(fragmented)}, Missing = {len(missing)}")
    print(f"  Total BUSCOs tracked: {len(all_statuses)}")

# Find intersection
intersection = all_orthologs['Cele']
for name in ['Ggal', 'Ncra', 'Scer']:
    intersection = intersection & all_orthologs[name]

print(f"\nIntersection (single-copy complete in ALL four): {len(intersection)}")

# Also show pairwise intersections
for n1 in datasets:
    for n2 in datasets:
        if n1 < n2:
            inter = all_orthologs[n1] & all_orthologs[n2]
            print(f"  {n1} ∩ {n2}: {len(inter)}")

# List the actual BUSCO IDs in the intersection
print(f"\nIntersection BUSCO IDs:")
for bid in sorted(intersection):
    print(f"  {bid}")
PYEOF

